function countAsmDataBytes(asm) {
  const lines = asm.split(/\r?\n/);
  let total = 0;
  for (const line of lines) {
    const clean = line.split(";")[0].trim();
    if (!clean) continue;
    const dbMatch = clean.match(/^db\s+(.+)$/i);
    if (dbMatch) {
      total += dbMatch[1].split(",").map((token) => token.trim()).filter((token) => token.length > 0).length;
      continue;
    }
    const dwMatch = clean.match(/^dw\s+(.+)$/i);
    if (dwMatch) {
      total += dwMatch[1].split(",").map((token) => token.trim()).filter((token) => token.length > 0).length * 2;
    }
  }
  return total;
}
