      residentEstimatedWindowOverflowCount: ascii16ResidentWindowOverflowCount,
      residentEstimatedWindowOverflowSamples: mapperWindow.targetFormat === "ascii16" ? ascii16ResidentWindowOverflowReport.samples : [],
